def skill():
    tot = 0
    for d in range(1, 31):
        if 30 % d:
            continue
        neg = sum(-30 + (k - 1)*d for k in range(1, 40) if -30 + (k - 1)*d < 0)
        if neg > -100:
            tot += d
    return tot

def standard():
    tot = 0
    for d in range(1, 200):
        a = lambda n: -30 + (n - 1)*d
        ga = any(abs(a(m)) == abs(a(m + 2)) for m in range(1, 400))
        s = 0; mn = 0
        for n in range(1, 400):
            s += a(n); mn = min(mn, s)
        if ga and mn > -100:
            tot += d
    return tot

def unique():
    return [standard()]
